/* Kryptik zone colours: the border colours dwl draws, and nothing else.
 *
 * GENERATED by tools/desktop/gen-zone-colours.py from compartments/zones/
 * ([ui] border_color of each zone); do not edit.
 *
 * X(zone, border, proxy, hold) - 0xRRGGBBAA, the uid of the zone's proxy,
 * and 1 if its file lets it hold the screen awake. dwl serves each zone
 * listed here a socket of its own, which takes only the session and that
 * uid, and draws its windows in its colour; a window whose client came
 * through dwl's own socket is drawn UNZONED.
 */
#ifndef KRYPTIK_ZONE_COLOURS_H
#define KRYPTIK_ZONE_COLOURS_H

#define KRYPTIK_ZONE_COLOURS(X) \
	X("dev",       0x7f623dff, 196607, 0) \
	X("net",       0x686573ff, 262143, 0) \
	X("personal",  0x009b79ff, 327679, 1) \
	X("untrusted", 0xba7c02ff, 393215, 0) \
	X("vault",     0x9e80acff, 458751, 0) \
	X("work",      0x2d60d1ff, 524287, 1)

#define KRYPTIK_UNZONED_BORDER  0xd8d8d8ff
#define KRYPTIK_URGENT_BORDER   0xffd000ff

#endif
